#include <stdio.h>
struct student {
  int num;
  char name[20];
  int score;
};
int main(void)
{
  struct student s[5];
  int i, k = 0;
  for (i = 0; i < 5; i++)
    scanf("%d%s%d", &s[i].num, s[i].name, &s[i].score);
  for (i = 1; i < 5; i++)
    if (s[i].score > s[k].score)
      k = i;
  printf("%d %s %d\n", s[k].num, s[k].name, s[k].score);
  return 0;
}

