#include <stdio.h>
struct node {
  int data;
  struct node *next;
};
int main(void)
{
  struct node a, b, c, *p;
  a.data = 1; b.data = 2; c.data = 3;
  a.next = &b; b.next = &c;
  c.next = NULL;
  p = &a;
  while (p != NULL) {
    printf("%d ", p->data * 10);
    p = p->next;
  }
  printf("\n");
  return 0;
}

